def handle(app, svc):
    resp = svc.apply(app)
    # API v2 response: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0)

    # Network referral rule: self_employed with requested_limit > 6000
    # must go to manual review instead of being issued (decline stays decline).
    force_review = (
        app.get("employment") == "self_employed"
        and app.get("requested_limit", 0) > 6000
    )

    if outcome == "approved":
        if force_review:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    else:  # manual_review
        return {"action": "queue_review", "limit": 0}

